H.background();
const lo = Math.round(H.clamp(P.lo, 1, 6));
const hiRaw = Math.round(H.clamp(P.hi, 1, 10));
const hi = Math.max(lo, hiRaw);
const c = P.c;
const summand = (k) => c * k;
const count = hi - lo + 1;
const revealed = lo + Math.floor((t * 1.1) % (count + 1));
const v = H.plot2d({ xMin: lo - 1, xMax: hi + 1, yMin: 0, yMax: Math.max(4, c * hi + 2) });
v.grid(); v.axes();
let running = 0;
for (let k = lo; k <= hi; k++) {
  const h = summand(k);
  const on = k < revealed;
  v.rect(k - 0.4, 0, 0.8, Math.max(0, h), { fill: on ? H.colors.accent : H.colors.panel, stroke: H.colors.axis, width: 1 });
  if (on) running += h;
  v.text(String(k), k, -0.0001, { color: H.colors.sub, size: 12, align: "center", baseline: "top" });
}
const cur = Math.min(revealed, hi);
v.dot(cur, Math.max(0.2, summand(cur)) + 0.4, { r: 6 + Math.sin(t * 4), fill: H.colors.warn });
const total = (function () { let s = 0; for (let k = lo; k <= hi; k++) s += summand(k); return s; })();
H.text("Σ  from k=" + lo + " to " + hi + "  of  " + c.toFixed(1) + "·k", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("each bar is one term c·k; the running total adds them left to right", 24, 52, { color: H.colors.sub, size: 13 });
H.text("running sum so far = " + running.toFixed(1) + "      full sum = " + total.toFixed(1), 24, H.H - 16, { color: H.colors.good, size: 13 });
H.legend([{ label: "added term", color: H.colors.accent }, { label: "now adding", color: H.colors.warn }], H.W - 170, 28);
